n, k = map(int, input().split())
d = list(map(int, input().split()))
o = {}
for e in d:
    if e in o:
        o[e] += 1
    else:
        o[e] = 1
l = list(o.copy())
l.sort()
p = []
for e in l.copy():
    for j in p.copy():
        if e - j <= k:
            l.remove(j)
            p.remove(j)
            n -= o[j]
