n, K = map(int, input().split())
array = list(map(int, input().split()))

array.sort()
count = 0;
i = 0;
c = 1;
while (i < len(array)- 1):
    val1 = array[i]
    val2 = array[i+1]
    #print (val1, val2)
    if (val1 == val2):
        j = i;
        #print ("condition 1")
        while (j < len(array)-1 and array[j] == array[j+1]):
            j = j + 1;
            c = c + 1;
        #print ("j = ", j)
        k = j + 1;
        if (k < len(array) and array[k] - array[j] <= K):
            #print ("cond true ", c)
            count = count + c
            c = 1;
        i = k;
        #print ("new i = ", i)
    elif (val2 > val1 and val2 - val1 <= K):
        count = count+1;
        #print (val2, val1)
        i = i + 1

print(n - count)
